<script lang="ts">
 import {onMount,tick} from 'svelte'
 import {terminalClosed,type FolderProject,type MachineHealth,type TerminalMachine,type TerminalSession} from './api'
 import TerminalIcon from './TerminalIcon.svelte'
 import SessionHoverCard from './SessionHoverCard.svelte'
 import { PROJECT_COLOURS as palette, projectColour, projectColourHex, type ProjectColour } from '../projectColour'
 import { PROJECT_CAP, needCount, needsInput, sanitiseCollapsed, statusLine, toggleCollapsed, visibleProjects } from './panelState'
 // layout: a docked column beside the terminal, a drawer over it (phones, an unpinned tablet), or the 64 px mini rail.
 // onclose is the chevron (collapseLabel names what it does); onexpand, onnewsession and the pin belong to the workspace.
 let {machines,sessions,selectedAgent,selectedSession,preferenceKey,onselect,onclose,onrefresh,onaction,ondisconnect,onnew,onagent,cancreate,busy=false,layout='docked',collapseLabel='Close session navigation',onexpand,onfind,onnewsession,pinnable=false,pinned=false,onpin,projects,projectRunning=new Map<string,number>(),currentProject='',onprojectstart,onprojectadd,onprojectcolour,health=[],serverNow=Date.now()}:{machines:TerminalMachine[];sessions:TerminalSession[];selectedAgent:string;selectedSession:string;preferenceKey:string;onselect:(item:TerminalSession)=>void;onclose:()=>void;onrefresh:()=>void;onaction:(kind:'rename'|'end'|'archive',item:TerminalSession)=>void;ondisconnect:()=>void;onnew:(id:string)=>void;onagent?:(id:string,opener:HTMLElement|null)=>void;cancreate:(id:string)=>boolean;busy?:boolean;layout?:'docked'|'drawer'|'mini';collapseLabel?:string;onexpand?:()=>void;onfind?:()=>void;onnewsession?:()=>void;pinnable?:boolean;pinned?:boolean;onpin?:()=>void;projects?:FolderProject[];projectRunning?:Map<string,number>;currentProject?:string;onprojectstart?:(project:FolderProject,opener:HTMLElement)=>void;onprojectadd?:(opener:HTMLElement)=>void;onprojectcolour?:(project:FolderProject,colour:ProjectColour)=>void;health?:MachineHealth[];serverNow?:number}=$props()
 let query=$state(''),sort=$state('custom'),group=$state('machine'),order=$state<string[]>([]),colors=$state<Record<string,string>>({}),notice=$state('')
 // Folded sections (Projects, Your sessions, and each group by key) are saved with the other layout choices. View holds Sort and Group.
 let collapsed=$state<string[]>([]),projectsExpanded=$state(false),viewOpen=$state(false)
 const isFolded=(key:string)=>collapsed.includes(key)
 function fold(key:string){collapsed=toggleCollapsed(collapsed,key);persist()}
 let menu=$state<HTMLElement>(),context=$state<{item:TerminalSession;x:number;y:number}|null>(null),machineContext=$state<{item:TerminalMachine;x:number;y:number}|null>(null),returnFocus:HTMLElement|undefined,dragging=''
 let projectMenu=$state<{item:FolderProject;x:number;y:number}|null>(null),projectFocus:HTMLElement|undefined
 let card=$state<{item:TerminalSession;x:number;y:number}|null>(null)
 const machineName=(id:string)=>machines.find(item=>item.agentId===id)?.host||'Unavailable machine'
 const projectOf=(item:TerminalSession)=>projects?.find(project=>project.id===item.projectId)
 // A session keeps the colour chosen for it; with none, it carries its project's identity colour.
 const sessionColour=(item:TerminalSession)=>colors[item.id]||projectOf(item)?.colour||''
 const sessionColourHex=(item:TerminalSession)=>projectColourHex(sessionColour(item))
 const healthOf=(id:string)=>health.find(item=>item.agentId===id)
 const projectSessions=(p:FolderProject)=>sessions.filter(item=>item.projectId===p.id)
 const newestProjectSession=(p:FolderProject)=>projectSessions(p).find(item=>['creating','running','end_requested'].includes(item.state))??projectSessions(p)[0]
 const matches=$derived(sessions.filter(item=>`${item.title} ${machineName(item.agentId)} ${item.state.replaceAll('_',' ')}`.toLowerCase().includes(query.toLowerCase())))
 // The header names what it counts: live sessions (the Show sessions badge counts the same), then any finished ones listed too.
 const liveCount=$derived(matches.filter(item=>['creating','running','end_requested'].includes(item.state)).length)
 const finishedCount=$derived(matches.length-liveCount)
 // Sessions waiting on the person, by project and overall: the badges that stay visible when a section is folded.
 const waitingProjects=$derived(new Set(sessions.filter(item=>item.projectId&&needsInput(item)).map(item=>item.projectId as string)))
 const projectNeeds=(p:FolderProject)=>needCount(projectSessions(p))
 const projectView=$derived(projects?visibleProjects(projects,projectRunning,waitingProjects,currentProject,projectsExpanded):{shown:[],hidden:0})
 const projectsNeed=$derived(projects?projects.reduce((n,p)=>n+projectNeeds(p),0):0)
 const sessionsNeed=$derived(needCount(matches))
 function ordered(list:TerminalSession[]){const ranked=new Map(order.map((id,i)=>[id,i]));return [...list].sort((a,b)=>{if(sort==='name')return a.title.localeCompare(b.title)||a.id.localeCompare(b.id);if(sort==='recent')return b.updatedAt-a.updatedAt||a.id.localeCompare(b.id);if(sort==='created')return b.createdAt-a.createdAt||a.id.localeCompare(b.id);if(sort==='status')return a.state.localeCompare(b.state)||a.title.localeCompare(b.title)||a.id.localeCompare(b.id);return (ranked.get(a.id)??Number.MAX_SAFE_INTEGER)-(ranked.get(b.id)??Number.MAX_SAFE_INTEGER)||a.createdAt-b.createdAt||a.id.localeCompare(b.id)})}
 const sorted=$derived(ordered(matches))
 // The mini rail lists every session (no machine filter or search), in the panel's order.
 const railSessions=$derived(ordered(sessions))
 const stateWord=(state:string)=>state.replaceAll('_',' ')
 const sortNames:Record<string,string>={custom:'custom order',name:'by name',recent:'recently updated',created:'newest first',status:'by status'}
 const groupNames:Record<string,string>={none:'no grouping',machine:'by machine',status:'by status',colour:'by colour'}
 // The rail's dot tells the state by shape as well as colour: running a filled circle, starting a ring, ending a half circle, lost a diamond, finished a hollow square.
 const dotShape=(state:string)=>state==='running'?'running':state==='creating'?'starting':state==='end_requested'?'ending':state==='lost'?'lost':'finished'
 const initial=(title:string)=>(Array.from(title.trim())[0]??'?').toLocaleUpperCase()
 function groupKey(item:TerminalSession){return group==='machine'?item.agentId:group==='status'?item.state:group==='colour'?(colors[item.id]||'none'):''}
 const groups=$derived.by(()=>{const out=new Map<string,{key:string;title:string;items:TerminalSession[]}>();for(const item of sorted){const key=groupKey(item);if(!out.has(key))out.set(key,{key,title:group==='machine'?machineName(key):group==='status'?key.replaceAll('_',' '):group==='colour'?(palette.find(c=>c.id===key)?.name||'No colour'):'',items:[]});out.get(key)!.items.push(item)}if(group==='machine')for(const machine of machines){if(!out.has(machine.agentId)&&(!query||machine.host.toLowerCase().includes(query.toLowerCase())))out.set(machine.agentId,{key:machine.agentId,title:machine.host,items:[]})}return [...out.values()]})
 // A new agent session starts on the selected session's machine, else the current machine, else the first that can take one.
 const agentForNew=$derived(sessions.find(item=>item.id===selectedSession)?.agentId||selectedAgent||machines.find(item=>cancreate(item.agentId))?.agentId||machines[0]?.agentId||'')
 function persist(){try{localStorage.setItem(preferenceKey,JSON.stringify({sort,group,order,colors,collapsed}))}catch{/* browser storage is optional */}}
 onMount(()=>{try{const saved=JSON.parse(localStorage.getItem(preferenceKey)||'{}');if(['custom','name','recent','created','status'].includes(saved.sort))sort=saved.sort;if(['none','machine','status','colour'].includes(saved.group))group=saved.group;collapsed=sanitiseCollapsed(saved.collapsed);if(Array.isArray(saved.order))order=[...new Set(saved.order.filter((v:unknown)=>typeof v==='string'))].slice(0,2000) as string[];if(saved.colors&&typeof saved.colors==='object'&&!Array.isArray(saved.colors))colors=Object.fromEntries(Object.entries(saved.colors).filter((entry):entry is [string,string]=>typeof entry[1]==='string'&&palette.some(c=>c.id===entry[1])))}catch{/* ignore an invalid preference */}})
 async function openMenu(event:MouseEvent|KeyboardEvent,item:TerminalSession){event.preventDefault();machineContext=null;returnFocus=event.currentTarget as HTMLElement;const box=returnFocus.getBoundingClientRect();context={item,x:Math.min(Math.max(8,'clientX'in event&&event.clientX?event.clientX:box.left),Math.max(8,innerWidth-240)),y:Math.max(8,Math.min('clientY'in event&&event.clientY?event.clientY:box.bottom,innerHeight-330))};await tick();menu?.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus()}
 async function openMachineMenu(event:MouseEvent|KeyboardEvent,id:string){const item=machines.find(m=>m.agentId===id);if(!item)return;event.preventDefault();context=null;returnFocus=event.currentTarget as HTMLElement;const box=returnFocus.getBoundingClientRect();machineContext={item,x:Math.min(Math.max(8,'clientX'in event&&event.clientX?event.clientX:box.left),Math.max(8,innerWidth-240)),y:Math.max(8,Math.min('clientY'in event&&event.clientY?event.clientY:box.bottom,innerHeight-190))};await tick();menu?.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus()}
 function newTerminal(id:string){closeMenu(false);onnew(id)}
 function newAgent(id:string){const opener=returnFocus??null;closeMenu(false);onagent?.(id,opener)}
 function closeMenu(focus=true){context=null;machineContext=null;if(focus)returnFocus?.focus()}
 function menuKey(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();closeMenu();return}if(event.key==='Tab'){closeMenu(false);return}if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();const buttons=[...menu!.querySelectorAll<HTMLElement>('button:not(:disabled),a[href]')],index=buttons.indexOf(document.activeElement as HTMLElement);buttons[event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}
 function action(kind:'rename'|'end'|'archive'){if(!context)return;const item=context.item;closeMenu(false);onaction(kind,item)}
 function colour(id:string){if(!context)return;colors={...colors,[context.item.id]:id};persist()}
 function move(id:string,target:string){if(id===target||sort!=='custom')return;const from=sessions.find(item=>item.id===id),to=sessions.find(item=>item.id===target);if(!from||!to)return;if(groupKey(from)!==groupKey(to)){notice='Move within a group, or choose No grouping to reorder across groups.';return}const ids=[...order,...sorted.map(item=>item.id)].filter((value,index,all)=>value!==id&&all.indexOf(value)===index);ids.splice(Math.max(0,ids.indexOf(target)),0,id);order=ids;notice='Session order saved in this browser.';persist()}
 function moveBy(delta:number){if(!context)return;const rows=groups.find(item=>item.key===groupKey(context!.item))?.items||[],index=rows.findIndex(item=>item.id===context!.item.id),target=rows[index+delta];if(!target)return;if(delta<0)move(context.item.id,target.id);else move(target.id,context.item.id)}
 function startDrag(event:DragEvent,item:TerminalSession){if(sort!=='custom'){event.preventDefault();return}dragging=item.id;event.dataTransfer?.setData('application/x-reet-session',item.id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
 function drop(event:DragEvent,item:TerminalSession){event.preventDefault();if(dragging&&event.dataTransfer?.getData('application/x-reet-session')===dragging)move(dragging,item.id);dragging=''}
 // A project's menu opens from its row (right-click), its menu button or Shift+F10. Starting a session and the colour
 // both belong to the project, so the panel offers them without sending the person to Home.
 function menuPoint(event:MouseEvent|KeyboardEvent,el:HTMLElement,width=230,height=260){const box=el.getBoundingClientRect();return{x:Math.min(Math.max(8,'clientX'in event&&event.clientX?event.clientX:box.left),Math.max(8,innerWidth-width)),y:Math.max(8,Math.min('clientY'in event&&event.clientY?event.clientY:box.bottom,innerHeight-height))}}
 async function openProjectMenu(event:MouseEvent|KeyboardEvent,p:FolderProject){event.preventDefault();context=null;machineContext=null;projectFocus=event.currentTarget as HTMLElement;projectMenu={item:p,...menuPoint(event,projectFocus)};await tick();menu?.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus()}
 function closeProjectMenu(focus=true){projectMenu=null;if(focus)projectFocus?.focus()}
 function startProject(p:FolderProject,opener:HTMLElement){closeProjectMenu(false);onprojectstart?.(p,opener)}
 function chooseProjectColour(p:FolderProject,id:ProjectColour){onprojectcolour?.(p,id)}
 function openProject(p:FolderProject){closeProjectMenu(false);const item=newestProjectSession(p);if(item)onselect(item)}
 // A session's card on hover or keyboard focus. It repeats the row's label, and the readings come from the machine's last
 // report, so a stale one is named as last known rather than drawn as live.
 function showCard(el:HTMLElement,item:TerminalSession){const box=el.getBoundingClientRect(),width=336,height=270;card={item,x:Math.min(Math.max(8,box.right+10),Math.max(8,innerWidth-width-8)),y:Math.min(Math.max(8,box.top-8),Math.max(8,innerHeight-height-8))}}
 function hideCard(){card=null}
</script>
<svelte:window onpointerdown={event=>{if((context||machineContext||projectMenu)&&!menu?.contains(event.target as Node)){closeMenu(false);closeProjectMenu(false)}}} onblur={()=>{closeMenu(false);closeProjectMenu(false);hideCard()}} onkeydown={event=>{if(event.key==='Escape')hideCard()}} />
{#if layout==='mini'}
<aside id="terminal-sessions" class="session-rail" aria-label="Session rail">
 <button class="rail-control rail-expand" onclick={onexpand} aria-label="Expand sessions" title="Expand sessions">»</button>
 <button class="rail-control" onclick={onnewsession} disabled={!machines.length} aria-label="New session" title="New session">+</button>
 <button class="rail-control" onclick={onfind} aria-label="Find sessions" title="Find sessions"><TerminalIcon name="search"/></button>
 <nav aria-label="Terminal sessions"><ul>{#each railSessions as item(item.id)}<li><button class="rail-session" aria-current={item.id===selectedSession?'true':undefined} aria-label={`${item.title} on ${machineName(item.agentId)}, ${needsInput(item)?`needs you, ${needsInput(item)}`:stateWord(item.state)}`} title={`${item.title}\n${machineName(item.agentId)} · ${needsInput(item)?`needs you, ${needsInput(item)}`:stateWord(item.state)}`} style={`--session-colour:${sessionColourHex(item)}`} onclick={()=>onselect(item)} onmouseenter={event=>showCard(event.currentTarget,item)} onmouseleave={hideCard} onfocus={event=>showCard(event.currentTarget,item)} onblur={hideCard} oncontextmenu={event=>openMenu(event,item)} onkeydown={event=>{if(event.key==='ContextMenu'||event.shiftKey&&event.key==='F10')void openMenu(event,item)}}><span class="rail-dot {needsInput(item)?'needs':dotShape(item.state)}" aria-hidden="true"></span><span aria-hidden="true">{initial(item.title)}</span></button></li>{/each}</ul></nav>
 <button class="rail-control" onclick={onclose} aria-label="Close session navigation" title="Close sessions">‹</button>
</aside>
{:else}
<aside id="terminal-sessions" class="session-sidebar" class:drawer={layout==='drawer'} aria-label="Session navigation">
 {#if onprojectstart && projects}
  <section class="projects" aria-label="Projects">
   <div class="projects-head"><button type="button" class="fold" aria-expanded={!isFolded('projects')} aria-controls="panel-projects-list" onclick={()=>fold('projects')}><span class="chev" class:folded={isFolded('projects')} aria-hidden="true"></span><h2>Projects</h2>{#if isFolded('projects')}<small>{projects.length}</small>{#if projectsNeed}<span class="need-badge" title={`${projectsNeed} waiting for you`} aria-label={`${projectsNeed} waiting for you`}>{projectsNeed}</span>{/if}{/if}</button><span class="projects-head-actions"><a class="link" href="/">Manage</a>{#if onprojectadd}<button type="button" class="project-action project-add" aria-label="Add a project" title="Add a project" onclick={event => onprojectadd(event.currentTarget)}>+</button>{/if}</span></div>
   {#if isFolded('projects')}
    <!-- Folded: the header carries the count and any waiting badge. -->
   {:else if projects.length}
    <ul id="panel-projects-list">
      {#each projectView.shown as p (p.id)}
       {@const live = projectRunning.get(p.id) ?? 0}
       {@const need = projectNeeds(p)}
       <li class:current={currentProject === p.id} class:needs={need > 0} style={`--project-colour:${projectColourHex(p.colour)}`}>
        <button type="button" class="project-row" aria-current={currentProject === p.id ? 'true' : undefined} aria-label={`${p.name}, ${need > 0 ? `${need} waiting for you, ` : ''}${live > 0 ? `${live} running` : 'no live sessions'}, on ${p.machine || 'a machine no longer enrolled'}`} onclick={() => openProject(p)} oncontextmenu={event => openProjectMenu(event, p)} onkeydown={event => { if (event.key === 'ContextMenu' || event.shiftKey && event.key === 'F10') void openProjectMenu(event, p) }}>
         <span class="project-dot" aria-hidden="true"></span>
         <span class="project-name">{p.name}</span>
         {#if need}<span class="need-badge" aria-hidden="true" title={`${need} waiting for you`}>{need}</span>{/if}
         {#if live}<small class="project-live" aria-hidden="true">{live}</small>{/if}
        </button>
        <button type="button" class="project-action" aria-label={`New session in ${p.name}`} title={cancreate(p.host) ? `New session in ${p.name}` : 'The machine is unavailable or this session limit is reached'} disabled={!cancreate(p.host)} onclick={event => startProject(p, event.currentTarget)}>+</button>
        <button type="button" class="project-action project-more" aria-label={`Actions for ${p.name}`} aria-haspopup="menu" aria-expanded={projectMenu?.item.id === p.id} onclick={event => openProjectMenu(event, p)}>⋮</button>
       </li>
      {/each}
    </ul>
    {#if projectView.hidden>0}<button type="button" class="link show-more" onclick={()=>projectsExpanded=true}>Show {projectView.hidden} more</button>{:else if projectsExpanded&&projects.length>PROJECT_CAP}<button type="button" class="link show-more" onclick={()=>projectsExpanded=false}>Show fewer</button>{/if}
   {:else}<p class="empty project-empty">Add a project to start an agent in one of your folders.</p>{/if}
  </section>
 {/if}
 <header><strong><button type="button" class="fold" aria-expanded={!isFolded('sessions')} aria-controls="panel-sessions-body" onclick={()=>fold('sessions')}><span class="chev" class:folded={isFolded('sessions')} aria-hidden="true"></span>Your sessions <small>{liveCount}</small>{#if finishedCount}{' '}<small class="finished">· {finishedCount} finished</small>{/if}{#if sessionsNeed}<span class="need-badge" title={`${sessionsNeed} waiting for you`} aria-label={`${sessionsNeed} waiting for you`}>{sessionsNeed}</span>{/if}</button></strong><span class="header-actions">{#if pinnable}<button class="pin" aria-pressed={pinned} onclick={onpin} title={pinned?'The panel stays open beside the terminal':'Keep the panel open beside the terminal'}>Keep open</button>{/if}<button class="collapse" onclick={onclose} aria-label={collapseLabel} title={collapseLabel}>‹</button></span></header>
 {#if onagent}<button class="new-agent" disabled={!agentForNew} onclick={event=>onagent(agentForNew,event.currentTarget)}>New agent session</button>{/if}
 {#if !isFolded('sessions')}<div id="panel-sessions-body" class="sessions-body">
 <label><span class="vh">Find sessions</span><input type="search" bind:value={query} placeholder="Find a session or machine…" aria-label="Find sessions" /></label>
 <button type="button" class="link view-toggle" aria-expanded={viewOpen} onclick={()=>viewOpen=!viewOpen}>{viewOpen?'Hide view options':'View options'} <small>· {sortNames[sort]}, {groupNames[group]}</small></button>
 {#if viewOpen}<div class="organise"><label>Sort<select aria-label="Sort sessions" value={sort} onchange={event=>{sort=event.currentTarget.value;persist()}}><option value="custom">Custom order</option><option value="name">Name</option><option value="recent">Recently updated</option><option value="created">Newest first</option><option value="status">Status</option></select></label><label>Group<select aria-label="Group sessions" value={group} onchange={event=>{group=event.currentTarget.value;persist()}}><option value="none">No grouping</option><option value="machine">Machine</option><option value="status">Status</option><option value="colour">Colour</option></select></label></div>{/if}
 <nav aria-label="Terminal sessions">{#each groups as section(section.key)}<section class="session-group">{#if section.title}{#if group==='machine'}<div class="machine-group-header"><h2><button type="button" class="fold" aria-expanded={!isFolded(`group:${section.key}`)} onclick={()=>fold(`group:${section.key}`)}><span class="chev" class:folded={isFolded(`group:${section.key}`)} aria-hidden="true"></span>{section.title}</button><small>{section.items.length}</small>{#if needCount(section.items)}<span class="need-badge" title={`${needCount(section.items)} waiting for you`} aria-label={`${needCount(section.items)} waiting for you`}>{needCount(section.items)}</span>{/if}</h2><button class="machine-new" aria-label={`New terminal on ${section.title}`} title={cancreate(section.key)?`New terminal on ${section.title}`:'Machine unavailable or terminal limit reached'} disabled={!cancreate(section.key)} onclick={()=>newTerminal(section.key)}>+</button><button class="machine-more" aria-label={`Actions for machine ${section.title}`} title="Machine terminal actions" onclick={event=>openMachineMenu(event,section.key)}>⋮</button></div>{:else}<h2><button type="button" class="fold" aria-expanded={!isFolded(`group:${section.key}`)} onclick={()=>fold(`group:${section.key}`)}><span class="chev" class:folded={isFolded(`group:${section.key}`)} aria-hidden="true"></span>{section.title}</button><small>{section.items.length}</small>{#if needCount(section.items)}<span class="need-badge" title={`${needCount(section.items)} waiting for you`} aria-label={`${needCount(section.items)} waiting for you`}>{needCount(section.items)}</span>{/if}</h2>{/if}{/if}{#if !(section.title&&isFolded(`group:${section.key}`))}<ul>{#each section.items as item(item.id)}<li class:selected={item.id===selectedSession} class:needs={!!needsInput(item)} style={`--session-colour:${sessionColourHex(item)}`} ondragover={event=>{if(dragging)event.preventDefault()}} ondrop={event=>drop(event,item)}>
  <button class="session-row" aria-current={item.id===selectedSession?'true':undefined} aria-label={`${item.title} on ${machineName(item.agentId)}${projectOf(item)?`, in ${projectOf(item)!.name}`:''}, ${needsInput(item)?`needs you, ${needsInput(item)}`:stateWord(item.state)}`} onclick={()=>onselect(item)} onmouseenter={event=>showCard(event.currentTarget,item)} onmouseleave={hideCard} onfocus={event=>showCard(event.currentTarget,item)} onblur={hideCard} oncontextmenu={event=>openMenu(event,item)} onkeydown={event=>{if(event.key==='ContextMenu'||event.shiftKey&&event.key==='F10')void openMenu(event,item)}}><span class="session-dot" class:running={item.state==='running'} class:needs={!!needsInput(item)} aria-hidden="true"></span><span><strong>{item.title}</strong><small>{group!=='machine'?`${machineName(item.agentId)} · `:''}{statusLine(item)}</small></span></button>
  <button class="row-actions" aria-label={`Actions for ${item.title}`} title={sort==='custom'?'Session actions · drag to reorder':'Session actions'} draggable={sort==='custom'} ondragstart={event=>startDrag(event,item)} ondragend={()=>dragging=''} onclick={event=>openMenu(event,item)} oncontextmenu={event=>openMenu(event,item)}>⋮</button>
 </li>{/each}</ul>{#if !section.items.length}<p class="empty machine-empty">No sessions yet.</p>{/if}{/if}</section>{:else}<p class="empty">{query?'No matching sessions.':'No sessions yet.'}</p>{/each}</nav>
 </div>{/if}
 {#if notice}<p class="notice" role="status">{notice}</p>{/if}<footer><button class="link" onclick={onrefresh}>Refresh status</button><a href="/machines">Manage machines →</a><small class="vh">Layout, colours and order saved in this browser. Use Custom order to drag sessions.</small></footer>
</aside>
{/if}
{#if context}<div class="session-context" role="menu" aria-label={`Actions for ${context.item.title}`} tabindex="-1" bind:this={menu} style={`left:${context.x}px;top:${context.y}px`} onkeydown={menuKey}>
 <p>{context.item.title}<small>{machineName(context.item.agentId)}</small></p>
 <button role="menuitem" disabled={busy||machines.find(m=>m.agentId===context!.item.agentId)?.serverEnabled===false} onclick={()=>action('rename')}>Rename session</button>
 <button role="menuitem" disabled={context.item.id!==selectedSession||terminalClosed(context.item.state)} onclick={()=>{closeMenu(false);ondisconnect()}}>Disconnect this browser</button>
 {#if terminalClosed(context.item.state)}<button role="menuitem" disabled={busy} onclick={()=>action('archive')}>Remove from history…</button>{:else}<button role="menuitem" class="danger" disabled={busy||machines.find(m=>m.agentId===context!.item.agentId)?.serverEnabled===false} onclick={()=>action('end')}>{context.item.state==='end_requested'?'Retry end request…':'Stop session…'}</button>{/if}
 <div class="menu-order"><button role="menuitem" disabled={sort!=='custom'} onclick={()=>moveBy(-1)}>Move up</button><button role="menuitem" disabled={sort!=='custom'} onclick={()=>moveBy(1)}>Move down</button></div>
 <span class="colour-label">Session colour</span><div class="colours">{#each palette as choice}<button role="menuitemradio" aria-checked={(colors[context.item.id]||'')===choice.id} aria-label={choice.name} title={choice.name} style={`--swatch:${choice.hex}`} onclick={()=>colour(choice.id)}>{choice.id===''?'×':''}</button>{/each}</div>
</div>{/if}
{#if projectMenu}<div class="session-context project-context" role="menu" aria-label={`Actions for ${projectMenu.item.name}`} tabindex="-1" bind:this={menu} style={`left:${projectMenu.x}px;top:${projectMenu.y}px`} onkeydown={menuKey}>
 <p>{projectMenu.item.name}<small>{projectMenu.item.machine || 'machine not enrolled'}</small></p>
 <button role="menuitem" disabled={!cancreate(projectMenu.item.host)} onclick={event => startProject(projectMenu!.item, projectFocus ?? (event.currentTarget as HTMLElement))}>New session here</button>
 <a role="menuitem" href={`/?project=${encodeURIComponent(projectMenu.item.id)}`}>Show on Home</a>
 <span class="colour-label">Project colour</span><div class="colours">{#each palette as choice}<button role="menuitemradio" aria-checked={projectColour(projectMenu.item.colour) === choice.id} aria-label={choice.name} title={choice.name} style={`--swatch:${choice.hex}`} onclick={() => chooseProjectColour(projectMenu!.item, choice.id)}>{choice.id === '' ? '×' : ''}</button>{/each}</div>
</div>{/if}
{#if machineContext}<div class="session-context" role="menu" aria-label={`Actions for machine ${machineContext.item.host}`} tabindex="-1" bind:this={menu} style={`left:${machineContext.x}px;top:${machineContext.y}px`} onkeydown={menuKey}>
 <p>{machineContext.item.host}<small>{machineContext.item.ready?'Ready for terminals':'Not ready for terminals'}</small></p>
 <button role="menuitem" disabled={!cancreate(machineContext.item.agentId)} onclick={()=>{if(machineContext)newTerminal(machineContext.item.agentId)}}>New terminal</button>
 {#if onagent}<button role="menuitem" onclick={()=>{if(machineContext)newAgent(machineContext.item.agentId)}}>New agent session</button>{/if}
 <a role="menuitem" href={`/machines?machine=${encodeURIComponent(machineContext.item.host)}`}>Manage machine…</a>
</div>{/if}
{#if card}<div class="session-card-pop" style={`left:${card.x}px;top:${card.y}px`}><SessionHoverCard session={card.item} host={machineName(card.item.agentId)} project={projectOf(card.item)?.name} colour={sessionColour(card.item)} health={healthOf(card.item.agentId)} {serverNow} href={`/sessions?agent=${encodeURIComponent(card.item.agentId)}&session=${encodeURIComponent(card.item.id)}`} /></div>{/if}
<style>
 .new-agent{min-height:34px;margin-top:-6px;padding:6px 10px;border:1px solid var(--line);border-radius:7px;background:var(--card);color:var(--accent-text);font-size:.74rem;font-weight:600;text-align:left;cursor:pointer}.new-agent:hover:not(:disabled){background:var(--tint);border-color:var(--accent)}.new-agent:disabled{opacity:.4;cursor:default}@media(pointer:coarse){.new-agent{min-height:40px}}
 .machine-group-header{display:flex;align-items:center;gap:4px;margin-bottom:5px}.machine-group-header h2{flex:1;align-items:center;min-width:0;margin:0}.machine-new,.machine-more{flex:none;min-width:28px;min-height:28px;border:1px solid transparent;border-radius:6px;background:none;color:var(--muted);font:500 1.15rem var(--sans);cursor:pointer}.machine-new:hover:not(:disabled),.machine-more:hover{color:var(--accent-text);background:var(--tint);border-color:var(--line)}.machine-new:disabled{opacity:.35;cursor:default}.machine-empty{margin:3px 0 0}.session-context>a{min-height:32px;border-radius:5px;padding:7px 9px;font-size:.72rem;color:var(--ink);text-decoration:none}.session-context>a:hover,.session-context>a:focus-visible{background:var(--tint)}
 .session-sidebar{position:relative;display:flex;flex-direction:column;gap:12px;background:var(--bg);border-right:1px solid var(--line);padding:14px;min-height:0;min-width:0;overflow:auto}header{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:.82rem}header small{color:var(--muted);font-size:.65rem;font-weight:400;margin-left:6px}.collapse{background:none;border:0;border-radius:5px;cursor:pointer;font-size:1.5rem;color:var(--muted);min-width:28px;min-height:28px}.collapse:hover{background:var(--tint);color:var(--accent-text)}label{display:grid;gap:5px;min-width:0;font-size:.65rem;color:var(--muted)}input:not([type=checkbox]),select{width:100%;min-width:0;min-height:34px;padding:6px 8px;font-size:.74rem}.organise{display:grid;grid-template-columns:1fr 1fr;gap:8px}.organise select{font-size:.68rem;min-height:30px;padding:5px}nav{display:grid;gap:16px;align-content:start}.session-group{min-width:0}.session-group h2{font-size:.64rem;color:var(--muted);margin:0 2px 7px;text-transform:capitalize;display:flex;gap:8px;overflow-wrap:anywhere}.session-group h2 small{margin-left:auto;font-size:.6rem;font-weight:400}ul{list-style:none;display:grid;gap:4px;margin:0;padding:0}li{display:flex;align-items:stretch;border:1px solid transparent;border-left:3px solid var(--session-colour);border-radius:7px;min-width:0}li.selected{background:var(--card);border-top-color:var(--line);border-right-color:var(--line);border-bottom-color:var(--line)}li:hover{background:var(--card)}.session-row{display:flex;gap:8px;align-items:flex-start;text-align:left;flex:1;min-width:0;padding:9px 5px;background:transparent;border:0;color:var(--ink);cursor:pointer}.session-row>span:last-child{display:grid;gap:4px;min-width:0}.session-row strong{font-size:.74rem;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.session-row small{font-size:.61rem;color:var(--muted);text-transform:capitalize;overflow-wrap:anywhere}.session-dot{height:6px;width:6px;flex:none;background:var(--muted);border-radius:50%;margin-top:5px}.session-dot.running{background:var(--good)}.row-actions{width:28px;flex:none;border:0;border-radius:5px;background:transparent;color:var(--muted);cursor:pointer;font-size:1.2rem}.row-actions[draggable=true]{cursor:grab}.row-actions:hover{color:var(--accent-text);background:var(--tint)}.empty,.notice{font-size:.72rem;color:var(--muted);line-height:1.6}.notice{margin:0}footer{margin-top:auto;display:grid;gap:12px;padding-top:16px}.link,footer>a{font-size:.7rem;text-decoration:none;text-align:left;border:0;background:none;padding:0;color:var(--accent-text);cursor:pointer}.link:hover,footer>a:hover{text-decoration:underline}footer small{font-size:.6rem;line-height:1.6;color:var(--muted)}.session-context{position:fixed;z-index:40;width:232px;max-height:calc(100dvh - 16px);overflow:auto;padding:6px;border:1px solid var(--line);border-radius:10px;background:var(--card);box-shadow:0 12px 35px rgb(0 0 0 / .2);display:grid;gap:2px}.session-context>p{font-size:.74rem;font-weight:600;overflow-wrap:anywhere;margin:5px 8px 8px}.session-context p small{display:block;font-size:.63rem;color:var(--muted);font-weight:400;margin-top:4px}.session-context button{min-height:32px;background:none;border:0;border-radius:5px;padding:7px 9px;text-align:left;font-size:.72rem;color:var(--ink);cursor:pointer}.session-context button:hover,.session-context button:focus-visible{background:var(--tint)}.session-context button:disabled{opacity:.4;cursor:default}.session-context button.danger{color:var(--bad)}.menu-order{border-top:1px solid var(--line);margin-top:4px;padding-top:4px;display:flex}.menu-order button{flex:1}.colour-label{font-size:.62rem;color:var(--muted);margin:8px}.colours{display:flex;gap:5px;padding:0 7px 6px}.colours button{border:1px solid var(--line);background:var(--swatch);padding:0;height:24px;width:24px;min-height:24px;text-align:center}.colours button[aria-checked=true]{outline:2px solid var(--ink);outline-offset:2px}.vh{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.session-sidebar.drawer{position:absolute;inset:0 auto 0 0;width:min(85%,var(--sidebar-width));z-index:8;box-shadow:12px 0 30px rgb(0 0 0 / .12)}@media(pointer:coarse){.machine-new,.machine-more{min-height:40px;min-width:36px}.collapse,.row-actions,.session-context button{min-height:40px}.colours button{height:30px;width:30px}}

 .header-actions{display:flex;align-items:center;gap:4px}.pin{min-height:28px;padding:3px 8px;border:1px solid var(--line);border-radius:6px;background:var(--card);color:var(--muted);font-size:.66rem;cursor:pointer}.pin[aria-pressed=true]{border-color:var(--accent);color:var(--accent-text);background:var(--tint)}.pin:hover{border-color:var(--accent)}
 /* The drawer slides in from the edge; with reduced motion it simply appears. */
 @media(prefers-reduced-motion:no-preference){.session-sidebar.drawer{animation:reet-drawer-in .16s ease-out}}
 @keyframes -global-reet-drawer-in{from{transform:translateX(-24px);opacity:0}to{transform:none;opacity:1}}
 /* Mini rail: 64 px, one 44 px button per session (state dot and initial; the name, machine and state are its label and tooltip). */
 .session-rail{display:flex;flex-direction:column;align-items:center;gap:6px;padding:10px 0;background:var(--bg);border-right:1px solid var(--line);min-height:0;min-width:0;overflow:hidden}.session-rail nav{display:block;flex:1;min-height:0;width:100%;overflow-y:auto;overflow-x:hidden;border-top:1px solid var(--line);padding-top:6px}.session-rail ul{justify-items:center;gap:6px}.session-rail li{border:0;display:block}
 .rail-control,.rail-session{position:relative;display:grid;place-items:center;width:44px;height:44px;flex:none;padding:0;border:1px solid transparent;border-radius:8px;background:none;color:var(--muted);font:600 .95rem var(--sans);cursor:pointer}.rail-control:hover:not(:disabled),.rail-session:hover{background:var(--card);border-color:var(--line);color:var(--accent-text)}.rail-control:disabled{opacity:.4;cursor:default}
 .rail-session{color:var(--ink);border-left:3px solid var(--session-colour)}.rail-session[aria-current=true]{background:var(--card);border-color:var(--line);border-left-color:var(--accent)}
 .rail-dot{position:absolute;top:6px;right:6px;width:9px;height:9px;box-sizing:border-box}.rail-dot.needs{border-radius:50%;background:var(--warn);box-shadow:0 0 0 2px color-mix(in srgb,var(--warn) 35%,transparent)}.rail-dot.running{border-radius:50%;background:var(--good)}.rail-dot.starting{border-radius:50%;border:2px solid var(--info)}.rail-dot.ending{border-radius:50%;border:1px solid var(--warn);background:linear-gradient(90deg,var(--warn) 50%,transparent 50%)}.rail-dot.lost{width:8px;height:8px;transform:rotate(45deg);background:var(--bad)}.rail-dot.finished{border-radius:1px;border:2px solid var(--muted)}
 /* Projects at the top of the panel: the same folder projects as Home, each with its own + and menu. The colour strip is
    identity; the count in green is live state, said separately. */
 .projects{display:grid;gap:6px;padding-bottom:10px;border-bottom:1px solid var(--line)}
 .projects-head{display:flex;align-items:center;gap:8px}
 .projects-head-actions{display:flex;align-items:center;gap:4px}
 .projects-head h2{margin:0;flex:1;font-size:.64rem;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--muted)}
 .projects ul{display:grid;gap:2px;margin:0;padding:0;list-style:none}
 .projects li{display:flex;align-items:center;gap:1px;min-width:0;border:1px solid transparent;border-left:3px solid var(--project-colour,transparent);border-radius:7px}
 .projects li:hover{background:var(--card)}
 .projects li.current{background:var(--card);border-top-color:var(--line);border-right-color:var(--line);border-bottom-color:var(--line)}
 .project-row{display:flex;flex:1;align-items:center;gap:7px;min-width:0;min-height:30px;padding:5px 4px;border:0;border-radius:6px;background:none;color:var(--ink);font:inherit;font-size:.74rem;text-align:left;cursor:pointer}
 .project-row:hover{background:var(--tint)}
 .project-dot{flex:none;width:7px;height:7px;border-radius:50%;background:var(--project-colour,transparent);border:1px solid var(--line-strong)}
 .project-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
 .project-live{flex:none;color:var(--good);font-size:.65rem;font-weight:600}
 .project-action{flex:none;display:grid;place-items:center;min-width:26px;min-height:26px;padding:0;border:1px solid transparent;border-radius:6px;background:none;color:var(--muted);font:500 1.05rem var(--sans);cursor:pointer}
 .project-action:hover:not(:disabled){color:var(--accent-text);background:var(--tint);border-color:var(--line)}
 .project-action:disabled{opacity:.35;cursor:default}
 .project-add{font-size:1.15rem}
 .project-empty{margin:2px 0 0}
 .project-more{font-size:.9rem}
 /* Fold buttons: a chevron and the section's name. A folded header keeps its count and the amber badge for anything waiting. */
 header>strong{min-width:0;flex:1}.fold{display:inline-flex;flex-wrap:wrap;align-items:center;gap:2px 6px;max-width:100%;min-width:0;min-height:26px;padding:0;border:0;background:none;color:inherit;font:inherit;text-transform:inherit;letter-spacing:inherit;cursor:pointer;text-align:left}
 .fold:hover{color:var(--accent-text)}.fold .chev{width:10px;color:var(--muted);font-size:.7rem}.fold .chev::before{content:'▾'}.fold .chev.folded::before{content:'▸'}.fold h2{margin:0;font:inherit;letter-spacing:inherit;text-transform:inherit;color:inherit}.fold small{color:var(--muted);font-size:.62rem;font-weight:400}
 .session-group h2 .fold{font-size:inherit;font-weight:inherit}
 .need-badge{display:inline-grid;place-items:center;min-width:16px;height:16px;padding:0 5px;border-radius:8px;background:var(--warn);color:var(--bg);font-size:.62rem;font-weight:700;line-height:1;margin-left:6px}
 .machine-group-header h2 .need-badge,.session-group h2 .need-badge{margin-left:0}
 .sessions-body{display:grid;gap:12px;min-width:0}
 .view-toggle{min-height:26px}.view-toggle small{color:var(--muted);font-size:.62rem}
 .show-more{padding:4px 6px}
 /* A session waiting on the person: an amber edge and a pulsing dot, so it reads at a glance without the bell. */
 li.needs{border-left-color:var(--warn);background:color-mix(in srgb,var(--warn) 10%,transparent)}.projects li.needs{border-left-color:var(--warn)}
 .session-dot.needs{background:var(--warn);box-shadow:0 0 0 3px color-mix(in srgb,var(--warn) 30%,transparent)}
 li.needs .session-row small{color:var(--warn);font-weight:600;text-transform:none}
 @media(prefers-reduced-motion:no-preference){.session-dot.needs{animation:reet-need-pulse 1.8s ease-in-out infinite}@keyframes reet-need-pulse{50%{box-shadow:0 0 0 5px color-mix(in srgb,var(--warn) 5%,transparent)}}}
 .project-context>a:hover,.project-context>a:focus-visible{background:var(--tint)}
 .session-card-pop{position:fixed;z-index:60;pointer-events:none}
 @media(pointer:coarse){.project-row{min-height:44px}.project-action{min-width:44px;min-height:44px}.projects-head .link{min-height:44px;display:inline-flex;align-items:center}}
 /* A touch tablet (651-1099 px, not a phone held sideways): every control in the panel is a 44 px target; desktops keep their density. */
 @media(pointer:coarse) and (min-width:651px) and (max-width:1099px) and (min-height:501px){.session-sidebar :global(:is(button,a[href],select,input,summary)){min-height:44px}.collapse,.row-actions,.pin,.fold,.view-toggle,.show-more,.projects-head .link,:global(.session-sidebar .machine-new),:global(.session-sidebar .machine-more){min-width:44px}.link,footer>a{display:inline-flex;align-items:center}.session-context button,.session-context a{min-height:44px;box-sizing:border-box}.session-context a{display:flex;align-items:center}.colours{flex-wrap:wrap}.colours button{width:44px;height:44px}.session-sidebar:not(.drawer){padding-right:36px}}
</style>
